// Un registro en avisos_enviados por cada correo, se haya enviado o no (R4: reprocesar fallidos).
// Un correo que cubre varias solicitudes (el resumen de F3) trae solicitud_ids: una fila por cada una.
const avisos = $('Recibir aviso').all();

return $input.all().flatMap((item, i) => {
  const aviso = avisos[i].json;
  const error = item.json.error;
  const solicitudes = Array.isArray(aviso.solicitud_ids) && aviso.solicitud_ids.length > 0
    ? aviso.solicitud_ids
    : [aviso.solicitud_id ?? null];
  return solicitudes.map((solicitud_id) => ({
    json: {
      solicitud_id,
      tipo_aviso: aviso.tipo_aviso,
      destinatario: aviso.destinatario,
      resultado: error ? 'fallida' : 'enviada',
      detalle: error ? String(error.message ?? error).slice(0, 500) : null,
    },
  }));
});
